@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container" style="overflow-y:auto; max-height:@MaxHeight">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="sentinelRef" class="infinite-scroll-sentinel"
             style="display:flex; justify-content:center; padding:1rem;">
            <div class="spinner-border text-secondary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
</div>

@code {
    private ElementReference sentinelRef;
    private IJSObjectReference? module;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? dotNetRef;
    private bool isLoading;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    /// <summary>CSS max-height for the scrollable container (default 80vh).</summary>
    [Parameter]
    public string MaxHeight { get; set; } = "80vh";

    /// <summary>
    /// How far from the bottom (in CSS pixels) the sentinel is placed via
    /// rootMargin so loading triggers early. Default is 100px.
    /// </summary>
    [Parameter]
    public int LoadThreshold { get; set; } = 100;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-ac0c14383658443c96364f22573db6a7/js/infinite-scroll.js"
            );
        }

        if (module is not null && HasMore && !isLoading)
        {
            await module.InvokeVoidAsync("observe", sentinelRef, dotNetRef, LoadThreshold);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (isLoading || !HasMore) return;

        isLoading = true;
        await OnLoadMore.InvokeAsync();
        isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            try { await module.InvokeVoidAsync("disconnect"); }
            catch (JSDisconnectedException) { }
            await module.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

let observer = null;

export function observe(sentinel, dotNetRef, thresholdPx) {
    disconnect();

    observer = new IntersectionObserver(
        entries => {
            if (entries.some(e => e.isIntersecting)) {
                dotNetRef.invokeMethodAsync("OnSentinelVisible");
            }
        },
        {
            root: sentinel.closest(".infinite-scroll-container"),
            rootMargin: `0px 0px ${thresholdPx}px 0px`,
        }
    );

    observer.observe(sentinel);
}

export function disconnect() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

